begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select private.catalog_store('test:detail','{}','[{"id":"rawg:42","externalId":"42","summary":"Full summary","description":"Full description","developers":["Studio"]}]',true);
select private.catalog_store('test:search','{}','[{"id":"rawg:42","externalId":"42","summary":"","title":"Title refreshed"}]',false);
select is((select document->>'description' from public.games where id='rawg:42'),'Full description','search preserves full description');
select is((select document->>'summary' from public.games where id='rawg:42'),'Full summary','search preserves full summary');
select is((select count(*)::int from public.games where external_id=42),1,'provider identity unique');
select throws_ok($$insert into public.games values('forged','rawg',42,'{}',false,now())$$,'23514',null,'provider identity constraint');
select ok((select relrowsecurity from pg_class where oid='public.games'::regclass),'public games uses RLS');
select ok((select relrowsecurity from pg_class where oid='private.catalog_cache'::regclass),'cache uses RLS');
select ok((select relrowsecurity from pg_class where oid='private.catalog_attempts'::regclass),'budget uses RLS');
set local role anon;
select is((select count(*)::int from public.games where id='rawg:42'),1,'anon reads public catalog');
select throws_ok($$insert into public.games(id,provider,external_id,document) values('rawg:43','rawg',43,'{}')$$,'42501',null,'anon cannot insert games');
select throws_ok($$update public.games set document='{}'$$,'42501',null,'anon cannot update games');
select throws_ok($$delete from public.games$$,'42501',null,'anon cannot delete games');
select throws_ok($$select * from private.catalog_cache$$,'42501',null,'anon cannot read cache');
select throws_ok($$insert into private.catalog_cache values('forged','{}',now(),now())$$,'42501',null,'anon cannot write cache');
select throws_ok($$delete from private.catalog_cache$$,'42501',null,'anon cannot delete cache');
select throws_ok($$select * from private.catalog_attempts$$,'42501',null,'anon cannot read budget');
select throws_ok($$insert into private.catalog_attempts values(now())$$,'42501',null,'anon cannot write budget');
select throws_ok($$update private.catalog_attempts set attempted_at=now()$$,'42501',null,'anon cannot update budget');
select throws_ok($$delete from private.catalog_attempts$$,'42501',null,'anon cannot delete budget');
select throws_ok($$select private.catalog_reserve()$$,'42501',null,'anon cannot reserve budget');
select throws_ok($$select private.catalog_store('forged','{}','[]',false)$$,'42501',null,'anon cannot invoke cache write');
reset role;
