reset role;
delete from private.catalog_attempts;
select is((select count(*)::int from generate_series(1,25) where private.catalog_reserve()),20,'global rolling minute admits twenty attempts');
select is((select count(*)::int from private.catalog_attempts),20,'rejected requests spend no additional attempts');
delete from private.catalog_attempts;
insert into private.catalog_attempts select greatest(date_trunc('month',clock_timestamp() at time zone 'UTC') at time zone 'UTC',clock_timestamp()-interval '2 minutes') from generate_series(1,1000);
select ok(not private.catalog_reserve() or (select count(*) from private.catalog_attempts where attempted_at >= (date_trunc('month',clock_timestamp() at time zone 'UTC') at time zone 'UTC')) < 1000,'monthly cap rejects attempt 1001 or respects natural UTC month rollover');
select throws_ok($$select private.catalog_store('large',to_jsonb(repeat('x',1048577)),'[]',false)$$,'23514',null,'bounded cached payload');
select private.catalog_store('eviction-'||n,'{}','[]',false) from generate_series(1,510) n;
select is((select count(*)::int from private.catalog_cache),500,'cache evicts to five hundred entries');
update private.catalog_cache set expires_at=now()-interval '1 second';
select private.catalog_store('after-expiry','{}','[]',false);
select is((select count(*)::int from private.catalog_cache),1,'expired cache is removed');
select * from finish();
rollback;
